expressionInfo.expression:
// ============================================================
// Country PES Overview Dashboard
// For Admin 0 popup
//
// Existing four-layer deployment.
//
// Data sources:
//   - PES Applications - Points
//       Full application population, including applications
//       without polygon geometry.
//
//   - PES Contracts
//       Contracted hectares, planted hectares and observed trees.
//
// IMPORTANT:
// Make sure the layer names in the web map are exactly:
//   - PES Applications - Points
//   - PES Contracts
// ============================================================


// ============================================================
// COUNTRY FIELD
// ============================================================

// Adjust this field if your Admin 0 layer uses a different country name field.
var country = $feature.admin0_pse_name;


// ============================================================
// APPLICATIONS POINTS VIEW
// Full population of applications
// ============================================================

var apps = Filter(
    FeatureSetByName(
        $map,
        "PES Applications - Points",
        [
            "StageCategory",
            "StageOrder",
            "IsContract",
            "HasMonitoring",
            "MonitoringOverdue",
            "VisitCount",
            "VisitsCompleted",
            "EstimatedArea",
            "ActivityType",
            "BeneficiaryGender",
            "FireRiskCategory",
            "LandCoverChanged",
            "Country"
        ],
        false
    ),
    "Country = @country AND StageCategory NOT IN ('Rejected', 'Archived')"
);


// ============================================================
// CONTRACTS VIEW
// Contracted area, planted area and observed trees
// ============================================================

var cons = Filter(
    FeatureSetByName(
        $map,
        "PES Contracts",
        [
            "contractedpesarea",
            "plantedareameasured",
            "observednumberoftrees",
            "country"
        ],
        false
    ),
    "country = @country"
);


// ============================================================
// EMPTY STATE
// ============================================================

var total = Count(apps);

if (total == 0) {
    return {
        type: "text",
        text: "<i>No active PES applications in " + country + " yet.</i>"
    };
}


// ============================================================
// APPLICATION COUNTS
// ============================================================

var inReview = Count(Filter(apps, "StageOrder >= 1 AND StageOrder <= 4"));
var validated = Count(Filter(apps, "StageOrder = 5"));
var recommended = Count(Filter(apps, "StageOrder = 6"));
var approved = Count(Filter(apps, "StageOrder = 7"));

var contracts = Count(Filter(apps, "IsContract = 1"));
var monitored = Count(Filter(apps, "HasMonitoring = 1"));
var overdue = Count(Filter(apps, "MonitoringOverdue = 1"));


// ============================================================
// VISIT SCHEDULE AGGREGATION
// ============================================================

var scheduled = Filter(apps, "VisitCount > 0");

var visitsDone = DefaultValue(Sum(scheduled, "VisitsCompleted"), 0);
var visitsExpected = DefaultValue(Sum(scheduled, "VisitCount"), 0);

var visitPct = 0;

if (visitsExpected > 0) {
    visitPct = Round((visitsDone / visitsExpected) * 100, 0);
}

if (visitPct < 0) {
    visitPct = 0;
}

if (visitPct > 100) {
    visitPct = 100;
}


// ============================================================
// AREA AND TREE AGGREGATION
// ============================================================

// Estimated area comes from Applications Points.
var estimatedHa = DefaultValue(Sum(apps, "EstimatedArea"), 0);

// Contracted / planted / observed trees come from PES Contracts.
var contractedHa = DefaultValue(Sum(cons, "contractedpesarea"), 0);
var plantedHa = DefaultValue(Sum(cons, "plantedareameasured"), 0);
var treesObs = DefaultValue(Sum(cons, "observednumberoftrees"), 0);

var areaPct = 0;

if (contractedHa > 0) {
    areaPct = Round((plantedHa / contractedHa) * 100, 1);
}

if (areaPct < 0) {
    areaPct = 0;
}

if (areaPct > 100) {
    areaPct = 100;
}


// ============================================================
// FIRE RISK AND LAND COVER CHANGE
// ============================================================

var fireLow = Count(Filter(apps, "FireRiskCategory = 'Low'"));
var fireMod = Count(Filter(apps, "FireRiskCategory = 'Moderate'"));
var fireHigh = Count(Filter(apps, "FireRiskCategory = 'High'"));
var fireVHigh = Count(Filter(apps, "FireRiskCategory = 'Very High'"));

var fireAny = fireLow + fireMod + fireHigh + fireVHigh;

var lcChangedCnt = Count(Filter(apps, "LandCoverChanged = 1"));
var lcKnownCnt = Count(Filter(apps, "LandCoverChanged IS NOT NULL"));


// ============================================================
// BENEFICIARY GENDER
// ============================================================

var femaleCnt = Count(Filter(apps, "BeneficiaryGender = 'Female'"));
var maleCnt = Count(Filter(apps, "BeneficiaryGender = 'Male'"));

var genderCnt = femaleCnt + maleCnt;


// ============================================================
// HTML HELPERS
// ============================================================

function tile(value, labelText, color) {
    return "<div style=\"flex:1 1 30%; min-width:80px; background:#f5f9f9; border:1px solid #e0e0e0; border-radius:6px; padding:8px 4px; text-align:center;\">"
        + "<div style=\"font-size:18px; font-weight:700; color:" + color + ";\">" + value + "</div>"
        + "<div style=\"font-size:9px; color:#666; text-transform:uppercase; letter-spacing:0.5px; margin-top:2px;\">" + labelText + "</div>"
        + "</div>";
}


function distBar(labelText, cnt, totalCnt, barColor) {
    if (cnt == 0 || totalCnt == 0) {
        return "";
    }

    var pct = Round((cnt / totalCnt) * 100, 0);

    if (pct < 0) {
        pct = 0;
    }

    if (pct > 100) {
        pct = 100;
    }

    return "<div style=\"margin-bottom:6px;\">"
        + "<div style=\"display:flex; justify-content:space-between; font-size:10px; color:#555; margin-bottom:2px;\">"
        + "<span style=\"font-weight:600;\">" + labelText + "</span>"
        + "<span style=\"font-weight:700; color:" + barColor + ";\">" + cnt + " (" + pct + "%)</span>"
        + "</div>"
        + "<div style=\"background:#e0e0e0; border-radius:4px; height:12px; width:100%; overflow:hidden;\">"
        + "<div style=\"background:" + barColor + "; height:12px; width:" + pct + "%; border-radius:4px;\"></div>"
        + "</div>"
        + "</div>";
}


function card(titleText, accentColor, body) {
    if (IsEmpty(body) || body == "") {
        return "";
    }

    return "<div style=\"background:#f7fafa; border-left:4px solid " + accentColor + "; border-radius:4px; margin-bottom:10px; padding:8px 12px 8px 8px;\">"
        + "<div style=\"font-size:10px; font-weight:700; color:" + accentColor + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;\">" + titleText + "</div>"
        + body
        + "</div>";
}


function progressBlock(titleText, doneTxt, pct, barColor) {
    if (pct < 0) {
        pct = 0;
    }

    if (pct > 100) {
        pct = 100;
    }

    return "<div style=\"background:#f5f9f9; border-radius:6px; padding:8px 12px; margin-bottom:10px; border:1px solid #e0e0e0;\">"
        + "<div style=\"display:flex; justify-content:space-between; font-size:11px; color:#666; margin-bottom:4px;\">"
        + "<span>" + titleText + "</span>"
        + "<span style=\"font-weight:700; color:" + barColor + ";\">" + doneTxt + "</span>"
        + "</div>"
        + "<div style=\"background:#e0e0e0; border-radius:6px; height:10px; width:100%; overflow:hidden;\">"
        + "<div style=\"background:" + barColor + "; height:10px; width:" + pct + "%; border-radius:6px;\"></div>"
        + "</div>"
        + "</div>";
}


// ============================================================
// ACTIVITY MIX
// Dynamic grouping, no hard-coded activity list.
// ============================================================

var activityRows = "";

var byActivity = OrderBy(
    GroupBy(
        apps,
        ["ActivityType"],
        [
            {
                name: "cnt",
                expression: "1",
                statistic: "COUNT"
            }
        ]
    ),
    "cnt DESC"
);

for (var g in byActivity) {
    var actName = DefaultValue(g["ActivityType"], "Unspecified");
    activityRows = activityRows + distBar(actName, g["cnt"], total, "#0d7377");
}


// ============================================================
// FIRE RISK PROFILE
// ============================================================

var fireRows = "";

if (fireAny > 0) {
    fireRows =
        distBar("Low", fireLow, fireAny, "#4caf50")
        + distBar("Moderate", fireMod, fireAny, "#ffb300")
        + distBar("High", fireHigh, fireAny, "#ef6c00")
        + distBar("Very High", fireVHigh, fireAny, "#c62828");

    if (lcKnownCnt > 0) {
        fireRows = fireRows
            + "<div style=\"font-size:10px; color:#666; margin-top:6px;\">&#127793; Land cover change: <b>"
            + lcChangedCnt + " of " + lcKnownCnt
            + "</b> parcel(s) have a different dominant land cover than at application time</div>";
    }
}


// ============================================================
// GENDER SPLIT
// ============================================================

var genderHtml = "";

if (genderCnt > 0) {
    var femPct = Round((femaleCnt / genderCnt) * 100, 0);

    if (femPct < 0) {
        femPct = 0;
    }

    if (femPct > 100) {
        femPct = 100;
    }

    var malePct = 100 - femPct;

    genderHtml =
        "<div style=\"display:flex; justify-content:space-between; font-size:10px; color:#555; margin-bottom:2px;\">"
        + "<span style=\"font-weight:600;\">Female " + femaleCnt + " (" + femPct + "%)</span>"
        + "<span style=\"font-weight:600;\">Male " + maleCnt + " (" + malePct + "%)</span>"
        + "</div>"
        + "<div style=\"display:flex; height:12px; border-radius:4px; overflow:hidden;\">"
        + "<div style=\"width:" + femPct + "%; background:#9c27b0;\"></div>"
        + "<div style=\"flex:1; background:#42a5f5;\"></div>"
        + "</div>";
}


// ============================================================
// STAGE DISTRIBUTION
// ============================================================

var stageRows =
    distBar("In review", inReview, total, "#90a4ae")
    + distBar("Validated", validated, total, "#ffb300")
    + distBar("Recommended", recommended, total, "#c0ca33")
    + distBar("Approved / contract stage", approved, total, "#2e7d32");


// ============================================================
// OPTIONAL SUMMARY FLAGS
// ============================================================

var alertText = "";

if (overdue > 0) {
    alertText =
        "<div style=\"background:#fbe9e7; color:#d84315; border-radius:6px; padding:6px 8px; margin-bottom:10px; font-size:11px; font-weight:700; text-align:center;\">"
        + "&#9888; " + overdue + " application(s) have overdue or unscheduled remaining monitoring visits"
        + "</div>";
}


// ============================================================
// BUILD DASHBOARD
// ============================================================

var html =
    "<div style=\"font-family:Segoe UI,sans-serif; font-size:13px; color:#1a1a2e;\">"

    // Header
    + "<div style=\"background:#0d7377; color:white; padding:10px 12px; border-radius:6px 6px 0 0; margin-bottom:10px;\">"
    + "<div style=\"font-size:15px; font-weight:700;\">" + country + "</div>"
    + "<div style=\"font-size:10px; opacity:0.9; margin-top:2px; text-transform:uppercase; letter-spacing:0.8px;\">PES Programme Overview</div>"
    + "</div>"

    // Optional alert
    + alertText

    // KPI row 1
    + "<div style=\"display:flex; gap:6px; margin-bottom:6px; flex-wrap:wrap;\">"
    + tile(total, "Active applications", "#0d7377")
    + tile(contracts, "Contracts", "#2e7d32")
    + tile(overdue, "Visits overdue", IIf(overdue > 0, "#d84315", "#9e9e9e"))
    + "</div>"

    // KPI row 2
    + "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">"
    + tile(Round(contractedHa, 0) + " ha", "Contracted area", "#0d7377")
    + tile(Round(plantedHa, 0) + " ha", "Planted area", "#4caf50")
    + tile(IIf(treesObs > 0, Text(treesObs, "#,###"), "-"), "Trees observed", "#607d8b")
    + "</div>"

    // Pipeline
    + card(
        "Pipeline by Stage",
        "#0d7377",
        stageRows
    )

    // Activity mix
    + card(
        "Activity Mix",
        "#14a085",
        activityRows
    )

    // Monitoring progress
    + IIf(
        visitsExpected > 0,
        progressBlock(
            "Monitoring visits completed",
            visitsDone + " of " + visitsExpected + " (" + visitPct + "%)",
            visitPct,
            IIf(overdue > 0, "#e64a19", "#2e7d32")
        ),
        ""
    )

    // Area progress
    + IIf(
        contractedHa > 0,
        progressBlock(
            "Planted vs contracted area",
            Round(plantedHa, 1) + " / " + Round(contractedHa, 1) + " ha (" + areaPct + "%)",
            areaPct,
            "#4caf50"
        ),
        ""
    )

    // Fire risk
    + card(
        "Fire Risk Profile - last 5 years",
        "#ef6c00",
        fireRows
    )

    // Gender
    + card(
        "Beneficiary Gender",
        "#9c27b0",
        genderHtml
    )

    // Footer
    + "<div style=\"text-align:center; font-size:10px; color:#aaa; margin-top:6px; padding-top:6px; border-top:1px solid #eee;\">"
    + monitored + " application(s) with completed visits"
    + "&nbsp;|&nbsp;" + Round(estimatedHa, 0) + " ha estimated at application"
    + "&nbsp;|&nbsp; excludes rejected and archived"
    + "</div>"

    + "</div>";


return {
    type: "text",
    text: html
};

// ============================================================
//  Community Forest — Popup Arcade
//  Adapts per country (CMR / GNQ / GAB / DRC)
//  Uses exact field names from hosted layer
//  Returns {type:"text", text:html} for Enterprise
// ============================================================

Expects($feature,
  "fid", "type", "reference", "community", "area_leg_h", "area_sig_h",
  "sup_ngo", "management", "country", "sup_calc", "commun_typ",
  "exploitata", "statut_att", "statut_amg", "date_con_d", "date_pgs",
  "date_con_p", "province", "situation", "country_1",
  "cmr_attributaire", "cmr_type_", "cmr_desc_type", "cmr_type_attr",
  "cmr_nom_fcom", "cmr_exploitant", "cmr_statu_conv", "cmr_statu_amgt",
  "cmr_date_con_d", "cmr_date_pgs", "cmr_date_con_p", "cmr_sup_sig_ha",
  "gnq_codigo", "gnq_nom_pblado", "gnq_local_dist", "gnq_num_regis",
  "gnq_fech_atrb", "gnq_texto_ofic", "gnq_auto_firma", "gnq_estad_atrb",
  "gnq_empr_explo", "gnq_sup_sig_ha", "gnq_estad_expl",
  "gab_type_", "gab_type_desc", "gab_nom_ass", "gab_nom_com",
  "gab_nom_ste", "gab_province", "gab_mode_expl", "gab_statu_conv",
  "gab_date_psg", "gab_date_con_p", "gab_date_con_d",
  "gab_observatn", "gab_sup_sig_ha",
  "drc_territoire", "drc_secteur", "drc_groupement", "drc_terroir",
  "drc_programme", "drc_finance", "drc_co_finance", "drc_agence",
  "drc_partenaire", "drc_annee", "drc_source_db", "drc_exploitati",
  "drc_certificat", "drc_foncier"
)

var ACCENT = "#1b5e20"
var f      = $feature

// ── helpers ──────────────────────────────────────────────────
function isBlank(x) {
  return IsEmpty(x) || Trim(Text(x)) == "" || Text(x) == "null"
}
function txt(x) {
  if (isBlank(x)) { return "" }
  var s = Text(x)
  s = Replace(s, "&", "&amp;")
  s = Replace(s, "<", "&lt;")
  return Replace(s, ">", "&gt;")
}
function haTxt(x) {
  if (isBlank(x)) { return "" }
  var n = Number(x)
  if (IsNan(n) || n <= 0) { return "" }
  return Text(Round(n, 0), "#,###") + " ha"
}
function dateTxt(x) {
  if (IsEmpty(x)) { return "" }
  var d = Text(Date(x), "DD MMM YYYY")
  if (isBlank(d) || d == "NaN NaN NaN") { return "" }
  return d
}
function row(label, value) {
  if (isBlank(value)) { return "" }
  return "<tr><td style=\"color:#666; width:46%; padding:4px 6px 4px 0; font-size:12px; vertical-align:top; white-space:nowrap\">" + label + "</td>"
       + "<td style=\"font-weight:600; font-size:12px; padding:4px 0; vertical-align:top; color:#1a1a2e\">" + value + "</td></tr>"
}
function tbl(rows) {
  if (isBlank(rows)) { return "" }
  return "<table style=\"width:100%; border-collapse:collapse\">" + rows + "</table>"
}
function section(title, accent, body) {
  if (isBlank(body)) { return "" }
  return "<div style=\"background:#f7fafa; border-left:4px solid " + accent + "; border-radius:4px; margin-bottom:10px; padding:8px 10px 8px 8px\">"
       + "<div style=\"font-size:10px; font-weight:700; color:" + accent + "; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px\">" + title + "</div>"
       + body + "</div>"
}
function chip(label, bg, fg) {
  return "<div style=\"background:" + bg + "; color:" + fg + "; padding:5px 10px; border-radius:6px; font-size:11px; font-weight:700; white-space:nowrap\">" + label + "</div>"
}
function tile(value, label, color) {
  return "<div style=\"flex:1 1 28%; min-width:75px; background:#f5f9f9; border:1px solid #e0e0e0; border-radius:6px; padding:8px 4px; text-align:center\">"
       + "<div style=\"font-size:15px; font-weight:700; color:" + color + "\">" + value + "</div>"
       + "<div style=\"font-size:9px; color:#666; text-transform:uppercase; letter-spacing:0.5px; margin-top:2px\">" + label + "</div></div>"
}
function bar(label, value, color, maxv) {
  if (isBlank(value) || value <= 0 || maxv <= 0) { return "" }
  var pct = Round((value / maxv) * 100, 0)
  return "<div style=\"margin-bottom:6px\"><div style=\"display:flex; justify-content:space-between; font-size:10px; color:#555; margin-bottom:2px\">"
       + "<span style=\"font-weight:600\">" + label + "</span>"
       + "<span style=\"font-weight:700; color:" + color + "\">" + haTxt(value) + "</span></div>"
       + "<div style=\"background:#e0e0e0; border-radius:4px; height:12px; width:100%; overflow:hidden\">"
       + "<div style=\"background:" + color + "; height:12px; width:" + pct + "%; border-radius:4px\"></div></div></div>"
}

// ── vocabularies ─────────────────────────────────────────────
var FLAG = Dictionary(
  "Cameroon",          "🇨🇲",
  "DRC",               "🇨🇩",
  "Equatorial Guinea", "🇬🇶",
  "Gabon",             "🇬🇦",
  "Republic of Congo", "🇨🇬",
  "CAR",               "🇨🇫"
)

var CONV_STATUS = Dictionary(
  "provisoire",              ["Convention provisoire",  "#fff8e1", "#ff8f00"],
  "definitive",              ["Convention définitive",  "#e8f5e9", "#2e7d32"],
  "provisiore",              ["Convention provisoire",  "#fff8e1", "#ff8f00"],
  "definitif",               ["Convention définitive",  "#e8f5e9", "#2e7d32"],
  "rejete",                  ["Rejetée",                "#ffebee", "#c62828"],
  "encours",                 ["En cours",               "#e3f2fd", "#1565c0"],
  "Approuve",                ["Approuvé",               "#e8f5e9", "#2e7d32"],
  "Approuvé",                ["Approuvé",               "#e8f5e9", "#2e7d32"],
  "Attribue",                ["Titre CFCL attribué",    "#e8f5e9", "#1b5e20"],
  "Titre CFCL attribué",     ["Titre CFCL attribué",    "#e8f5e9", "#1b5e20"],
  "Titre CFCL attribue",     ["Titre CFCL attribué",    "#e8f5e9", "#1b5e20"]
)

var MGMT_STATUS = Dictionary(
  "en_cours",       ["PSG en élaboration", "#fff8e1", "#ff8f00"],
  "non_amenage",    ["Non aménagé",        "#eceff1", "#607d8b"],
  "amenge",         ["PSG approuvé",       "#e8f5e9", "#2e7d32"],
  "en_revision",    ["PSG en révision",    "#e3f2fd", "#1565c0"],
  "revise",         ["PSG révisé",         "#e8f5e9", "#1b5e20"],
  "in_preparation", ["PSG en élaboration", "#fff8e1", "#ff8f00"],
  "approved",       ["PSG approuvé",       "#e8f5e9", "#2e7d32"]
)

// ── detect country ───────────────────────────────────────────
var country = DefaultValue(f.country, "")
var flag    = IIf(HasKey(FLAG, country), FLAG[country], "🌍")

// ── resolve name area convention and province per country ────
var name    = ""
var area    = 0
var areaLbl = "Superficie SIG"
var convRaw = ""
var mgmtRaw = ""
var prov    = DefaultValue(f.province, "")

if (country == "Cameroon") {
  name    = DefaultValue(f.cmr_nom_fcom,
            DefaultValue(f.cmr_attributaire, f.reference))
  area    = Number(DefaultValue(f.cmr_sup_sig_ha, 0))
  convRaw = DefaultValue(f.cmr_statu_conv, "")
  mgmtRaw = DefaultValue(f.cmr_statu_amgt, "")
}
else if (country == "Equatorial Guinea") {
  name    = DefaultValue(f.gnq_nom_pblado,
            DefaultValue(f.gnq_codigo, f.reference))
  area    = Number(Replace(Text(DefaultValue(f.gnq_sup_sig_ha, "0")), ",", "."))
  convRaw = DefaultValue(f.gnq_estad_atrb, "")
  mgmtRaw = DefaultValue(f.gnq_estad_expl, "")
  prov    = DefaultValue(f.gnq_local_dist, prov)
}
else if (country == "Gabon") {
  name    = DefaultValue(f.gab_nom_com,
            DefaultValue(f.gab_nom_ass, f.reference))
  area    = Number(DefaultValue(f.gab_sup_sig_ha, 0))
  convRaw = DefaultValue(f.gab_statu_conv, "")
  mgmtRaw = DefaultValue(f.gab_mode_expl, "")
  prov    = DefaultValue(f.gab_province, prov)
}
else if (country == "DRC") {
  name    = DefaultValue(f.drc_terroir,
            DefaultValue(f.drc_groupement,
            DefaultValue(f.drc_territoire,
            DefaultValue(f.community, f.reference))))
  area    = Number(DefaultValue(f.area_sig_h,
            DefaultValue(f.area_leg_h, 0)))
  areaLbl = "Superficie ha"
  convRaw = DefaultValue(f.statut_att, "")
  mgmtRaw = DefaultValue(f.statut_amg, "")
}
else {
  name    = DefaultValue(f.reference, DefaultValue(f.community, "Sans nom"))
  area    = Number(DefaultValue(f.area_sig_h, DefaultValue(f.area_leg_h, 0)))
  convRaw = DefaultValue(f.statut_att, "")
  mgmtRaw = DefaultValue(f.statut_amg, "")
}

if (isBlank(name)) { name = DefaultValue(f.reference, "Sans nom") }
var typeRaw    = DefaultValue(f.type, "Forêt communautaire")
var forestType = IIf(typeRaw == "CFCL_LIM", "CFCL Limit",
                 IIf(typeRaw == "CFCL_AFF", "CFCL Affectation",
                 typeRaw))

// ── status chips ─────────────────────────────────────────────
var convArr = IIf(HasKey(CONV_STATUS, convRaw), CONV_STATUS[convRaw], null)
var mgmtArr = IIf(HasKey(MGMT_STATUS, mgmtRaw), MGMT_STATUS[mgmtRaw], null)

var chips = ""
if (!IsEmpty(convArr)) { chips += chip(convArr[0], convArr[1], convArr[2]) }
if (!IsEmpty(mgmtArr)) { chips += chip(mgmtArr[0], mgmtArr[1], mgmtArr[2]) }
if (IsEmpty(convArr) && !isBlank(convRaw)) {
  chips += chip(txt(convRaw), "#e3f2fd", "#1565c0")
}
if (IsEmpty(mgmtArr) && !isBlank(mgmtRaw)) {
  chips += chip(txt(mgmtRaw), "#f3e5f5", "#6a1b9a")
}

var chipsHtml = IIf(chips == "", "",
  "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap\">"
  + chips + "</div>")

// ── banner ───────────────────────────────────────────────────
var banner =
  "<div style=\"background:" + ACCENT + "; color:white; padding:10px 12px;"
  + "border-radius:6px 6px 0 0; margin:0 0 10px 0\">"
  + "<div style=\"font-size:15px; font-weight:700\">" + txt(name) + "</div>"
  + "<div style=\"font-size:11px; opacity:0.9; margin-top:2px\">"
  + flag + " " + txt(country)
  + IIf(country == "DRC",
        IIf(!isBlank(f.drc_terroir) && f.drc_terroir != name,
            " — " + txt(f.drc_terroir), ""),
        IIf(!isBlank(f.community) && f.community != name,
            " — " + txt(f.community), ""))
  + "</div>"
  + "<div style=\"font-size:10px; opacity:0.85; margin-top:4px;"
  + "text-transform:uppercase; letter-spacing:0.8px\">"
  + txt(forestType) + "</div></div>"

// ── breadcrumb ───────────────────────────────────────────────
var crumbs = txt(country)
if (!isBlank(prov)) { crumbs += " › " + txt(prov) }
if (country == "DRC") {
  if (!isBlank(f.drc_territoire)) { crumbs += " › " + txt(f.drc_territoire) }
  if (!isBlank(f.drc_secteur))    { crumbs += " › " + txt(f.drc_secteur) }
}
var crumbHtml =
  "<div style=\"background:#e8f5e9; border-radius:6px; padding:7px 8px;"
  + "margin-bottom:10px; font-size:12px; color:#2e7d32; font-weight:500\">"
  + "📍 " + crumbs + "</div>"

// ── tiles ────────────────────────────────────────────────────
var convYear = ""
if      (country == "Cameroon" && !IsEmpty(f.cmr_date_con_d)) {
  convYear = Text(Date(f.cmr_date_con_d), "YYYY")
}
else if (country == "Gabon" && !IsEmpty(f.gab_date_con_d)) {
  convYear = Text(Date(f.gab_date_con_d), "YYYY")
}
else if (country == "DRC" && !isBlank(f.drc_annee)) {
  convYear = txt(f.drc_annee)
}
else if (!IsEmpty(f.date_con_d)) {
  convYear = Text(Date(f.date_con_d), "YYYY")
}

var tiles =
  "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap\">"
  + tile(IIf(area > 0, Text(Round(area, 0), "#,###") + " ha", "—"),
         areaLbl, ACCENT)
  + tile(IIf(!isBlank(convYear), convYear, "—"),
         IIf(country == "DRC", "Année", "Convention"), "#607d8b")
  + tile(IIf(!isBlank(prov), txt(prov), "—"), "Province", "#2e7d32")
  + "</div>"

// ── area comparison bars ─────────────────────────────────────
var aLeg  = Number(DefaultValue(f.area_leg_h, 0))
var aSig  = IIf(country == "Cameroon",
                Number(DefaultValue(f.cmr_sup_sig_ha, 0)),
           IIf(country == "Gabon",
                Number(DefaultValue(f.gab_sup_sig_ha, 0)),
           IIf(country == "Equatorial Guinea",
                Number(Replace(Text(DefaultValue(f.gnq_sup_sig_ha, "0")), ",", ".")),
                Number(DefaultValue(f.area_sig_h, 0)))))
var aCalc = Number(DefaultValue(f.sup_calc, 0))
var maxA  = 0
for (var av in [aLeg, aSig, aCalc]) { if (av > maxA) { maxA = av } }

var areaCard = section("📐 Comparaison des superficies", "#1565c0",
  bar("Superficie légale",   aLeg,  "#607d8b", maxA) +
  bar("Superficie SIG",      aSig,  "#1565c0", maxA) +
  bar("Superficie calculée", aCalc, ACCENT,    maxA))

// ── country sections ─────────────────────────────────────────
var countrySection = ""

// ── CAMEROON ─────────────────────────────────────────────────
if (country == "Cameroon") {
  var cmrRows =
    row("Nom forêt comm.",   txt(f.cmr_nom_fcom)) +
    row("Attributaire",      txt(f.cmr_attributaire)) +
    row("Type attributaire", txt(f.cmr_type_attr)) +
    row("Description",       txt(f.cmr_desc_type)) +
    row("Exploitant",        txt(f.cmr_exploitant)) +
    row("Statut convention", txt(f.cmr_statu_conv)) +
    row("Statut aménagt.",   txt(f.cmr_statu_amgt)) +
    row("Superficie SIG ha", haTxt(f.cmr_sup_sig_ha)) +
    row("Conv. définitive",  dateTxt(f.cmr_date_con_d)) +
    row("Conv. provisoire",  dateTxt(f.cmr_date_con_p)) +
    row("Plan de gestion",   dateTxt(f.cmr_date_pgs))
  countrySection = section("🇨🇲 Champs Cameroun", "#E65100", tbl(cmrRows))
}

// ── EQUATORIAL GUINEA ────────────────────────────────────────
else if (country == "Equatorial Guinea") {
  var gnqRows =
    row("Nom poblado",       txt(f.gnq_nom_pblado)) +
    row("Codigo",            txt(f.gnq_codigo)) +
    row("N° registro",       txt(f.gnq_num_regis)) +
    row("District local",    txt(f.gnq_local_dist)) +
    row("Fecha atribución",  txt(f.gnq_fech_atrb)) +
    row("Texto oficial",     txt(f.gnq_texto_ofic)) +
    row("Autoridad firma",   txt(f.gnq_auto_firma)) +
    row("Estado atrib.",     txt(f.gnq_estad_atrb)) +
    row("Empresa explo.",    txt(f.gnq_empr_explo)) +
    row("Estado explo.",     txt(f.gnq_estad_expl)) +
    row("Superficie SIG ha", txt(f.gnq_sup_sig_ha))
  countrySection = section("🇬🇶 Champs Guinée Équatoriale", "#1B5E20", tbl(gnqRows))
}

// ── GABON ────────────────────────────────────────────────────
else if (country == "Gabon") {
  var gabRows =
    row("Nom communauté",    txt(f.gab_nom_com)) +
    row("Nom association",   txt(f.gab_nom_ass)) +
    row("Nom société",       txt(f.gab_nom_ste)) +
    row("Province",          txt(f.gab_province)) +
    row("Mode exploitation", txt(f.gab_mode_expl)) +
    row("Statut convention", txt(f.gab_statu_conv)) +
    row("Type description",  txt(f.gab_type_desc)) +
    row("Superficie SIG ha", haTxt(f.gab_sup_sig_ha)) +
    row("Date plan gest.",   txt(f.gab_date_psg)) +
    row("Conv. définitive",  dateTxt(f.gab_date_con_d)) +
    row("Conv. provisoire",  dateTxt(f.gab_date_con_p)) +
    row("Observation",       txt(f.gab_observatn))
  countrySection = section("🇬🇦 Champs Gabon", "#BF360C", tbl(gabRows))
}

// ── DRC — three dedicated sections ───────────────────────────
else if (country == "DRC") {

  // Section 1 — Concession details
    var drcConcRows =
    row("Communauté",        txt(DefaultValue(f.drc_terroir, f.community))) +
    row("Type",              txt(f.type)) +
    row("Statut",            txt(f.statut_att)) +
    row("Exploitation",      txt(f.drc_exploitati)) +
    row("Foncier",           txt(f.drc_foncier)) +
    row("Certificat",        txt(f.drc_certificat)) +
    row("Superficie ha",     haTxt(f.area_sig_h)) +
    row("Superficie légale", haTxt(f.area_leg_h))

  // Section 2 — Localisation
  var drcLocRows =
    row("Province",          txt(f.province)) +
    row("Territoire",        txt(f.drc_territoire)) +
    row("Secteur",           txt(f.drc_secteur)) +
    row("Groupement",        txt(f.drc_groupement)) +
    row("Terroir",           txt(f.drc_terroir))

  // Section 3 — Programme and financing
  var drcProgRows =
    row("Programme",         txt(f.drc_programme)) +
    row("Financement",       txt(f.drc_finance)) +
    row("Co-financement",    txt(f.drc_co_finance)) +
    row("Agence",            txt(f.drc_agence)) +
    row("Partenaire",        txt(f.drc_partenaire)) +
    row("Année",             txt(f.drc_annee)) +
    row("Source BD",         txt(f.drc_source_db))

  countrySection =
    section("🇨🇩 Concession — DRC", "#0D47A1", tbl(drcConcRows)) +
    section("📍 Localisation — DRC", "#00695c", tbl(drcLocRows)) +
    section("📋 Programme et financement", "#5d4037", tbl(drcProgRows))
}

// ── OTHER ────────────────────────────────────────────────────
else {
  var otherRows =
    row("Référence",  txt(f.reference)) +
    row("Communauté", txt(f.community)) +
    row("Management", txt(f.management)) +
    row("Exploitant", txt(f.exploitata))
  countrySection = section("🌍 Autres champs", "#37474F", tbl(otherRows))
}

// ── footer ───────────────────────────────────────────────────
var footer =
  "<div style=\"text-align:center; font-size:10px; color:#aaa;"
  + "margin-top:10px; padding-top:8px; border-top:1px solid #eee\">"
  + "🌳 Community Forest &nbsp;|&nbsp; " + txt(country)
  + " &nbsp;|&nbsp; FID : " + Text(f.fid)
  + "</div>"

// ── assemble ─────────────────────────────────────────────────
var popup =
  "<div style=\"font-family:Segoe UI,sans-serif; font-size:13px; color:#1a1a2e\">"
  + banner
  + chipsHtml
  + crumbHtml
  + tiles
  + areaCard
  + countrySection
  + footer
  + "</div>"

return { type: "text", text: popup }

// ============================================================
//  Logging Concession — Popup Arcade
//  Fields from hosted Concession_Forestiere layer
//  Adapts per country using pays field
//  Returns {type:"text", text:html} for Enterprise Portal
// ============================================================

Expects($feature,
  "pays", "province", "nom_de_la", "référenc", "attributai",
  "exploitant", "statut_jur", "statut_att", "statu_amgt",
  "statu_ccf", "num_ga", "ref_ccf", "date_attr", "date_echea",
  "date_d_att", "date_de_cl", "date_de_ce", "date_class",
  "plan_d_amt", "certificat", "certific_1", "statutcert",
  "orig_capit", "origine_de", "origine_du", "commentair",
  "sup_adm_ha", "sup_sig_ha", "sup_ccf_ha", "sup_fin",
  "sum_supe_1", "rfa_ha", "nom_foret", "nom_conces",
  "dénominat", "numero_de", "code_du_pa", "code_type",
  "statut_du", "classement", "statu_clas", "statu_cert",
  "situation", "ofac_id", "type_"
)

var ACCENT = "#5d4037"
var f      = $feature

// ── helpers ──────────────────────────────────────────────────
function isBlank(x) {
  return IsEmpty(x) || Trim(Text(x)) == "" || Text(x) == "null"
}
function txt(x) {
  if (isBlank(x)) { return "" }
  var s = Text(x)
  s = Replace(s, "&", "&amp;")
  s = Replace(s, "<", "&lt;")
  return Replace(s, ">", "&gt;")
}
function haTxt(x) {
  if (isBlank(x)) { return "" }
  var n = Number(x)
  if (IsNan(n) || n <= 0) { return "" }
  return Text(Round(n, 0), "#,###") + " ha"
}
function dateTxt(x) {
  if (IsEmpty(x)) { return "" }
  var d = Text(Date(x), "DD MMM YYYY")
  if (isBlank(d) || d == "NaN NaN NaN") { return "" }
  return d
}
function dateStrTxt(x) {
  if (isBlank(x)) { return "" }
  return txt(x)
}
function row(label, value) {
  if (isBlank(value)) { return "" }
  return "<tr><td style=\"color:#666;width:46%;padding:4px 6px 4px 0;font-size:12px;vertical-align:top;white-space:nowrap\">" + label + "</td>"
       + "<td style=\"font-weight:600;font-size:12px;padding:4px 0;vertical-align:top;color:#1a1a2e\">" + value + "</td></tr>"
}
function tbl(rows) {
  if (isBlank(rows)) { return "" }
  return "<table style=\"width:100%;border-collapse:collapse\">" + rows + "</table>"
}
function section(title, accent, body) {
  if (isBlank(body)) { return "" }
  return "<div style=\"background:#f7fafa;border-left:4px solid " + accent + ";border-radius:4px;margin-bottom:10px;padding:8px 10px 8px 8px\">"
       + "<div style=\"font-size:10px;font-weight:700;color:" + accent + ";text-transform:uppercase;letter-spacing:0.8px;margin-bottom:8px\">" + title + "</div>"
       + body + "</div>"
}
function chip(label, bg, fg) {
  return "<div style=\"background:" + bg + ";color:" + fg + ";padding:5px 10px;border-radius:6px;font-size:11px;font-weight:700;white-space:nowrap\">" + label + "</div>"
}
function tile(value, label, color) {
  return "<div style=\"flex:1 1 28%;min-width:75px;background:#f5f9f9;border:1px solid #e0e0e0;border-radius:6px;padding:8px 4px;text-align:center\">"
       + "<div style=\"font-size:15px;font-weight:700;color:" + color + "\">" + value + "</div>"
       + "<div style=\"font-size:9px;color:#666;text-transform:uppercase;letter-spacing:0.5px;margin-top:2px\">" + label + "</div></div>"
}
function bar(label, value, color, maxv) {
  if (isBlank(value) || value <= 0 || maxv <= 0) { return "" }
  var pct = Round((value / maxv) * 100, 0)
  return "<div style=\"margin-bottom:6px\"><div style=\"display:flex;justify-content:space-between;font-size:10px;color:#555;margin-bottom:2px\">"
       + "<span style=\"font-weight:600\">" + label + "</span>"
       + "<span style=\"font-weight:700;color:" + color + "\">" + haTxt(value) + "</span></div>"
       + "<div style=\"background:#e0e0e0;border-radius:4px;height:12px;width:100%;overflow:hidden\">"
       + "<div style=\"background:" + color + ";height:12px;width:" + pct + "%;border-radius:4px\"></div></div></div>"
}

// ── vocabularies ─────────────────────────────────────────────
var FLAG = Dictionary(
  "Cameroon",          "🇨🇲",
  "DRC",               "🇨🇩",
  "Equatorial Guinea", "🇬🇶",
  "Republic of Congo", "🇨🇬",
  "Gabon",             "🇬🇦",
  "CAR",               "🇨🇫"
)

var SIT_COLORS = Dictionary(
  "complete",      ["✅ Complet",           "#e8f5e9", "#2e7d32"],
  "part_complete", ["⚠️ Partiel",           "#fff8e1", "#ff8f00"],
  "no_data",       ["❌ Données manquantes", "#ffebee", "#c62828"]
)

var STATU_CCF = Dictionary(
  "signe",   ["Signé",        "#e8f5e9", "#2e7d32"],
  "retro",   ["Rétrocédé",    "#ffebee", "#c62828"],
  "non_co",  ["Non converti", "#eceff1", "#607d8b"],
  "resili",  ["Résilié",      "#ffebee", "#c62828"],
  "valide",  ["Validé",       "#e8f5e9", "#2e7d32"]
)

var STATU_AMGT = Dictionary(
  "En cour",  ["Aménagement en cours",  "#fff8e1", "#ff8f00"],
  "Revisio",  ["Plan en révision",      "#e3f2fd", "#1565c0"],
  "Depose",   ["Plan déposé",           "#f3e5f5", "#6a1b9a"],
  "Valide",   ["Plan validé",           "#e8f5e9", "#2e7d32"],
  "Amenage",  ["Aménagé",               "#e8f5e9", "#1b5e20"]
)

// ── core values ───────────────────────────────────────────────
var country   = DefaultValue(f.pays, "")
var flag      = IIf(HasKey(FLAG, country), FLAG[country], "🌍")
var situation = DefaultValue(f.situation, "")
var province  = DefaultValue(f.province, "")

// Primary name — nom_de_la first then fallbacks
var name = DefaultValue(f.nom_de_la,
           DefaultValue(f.dénominat,
           DefaultValue(f.nom_foret,
           DefaultValue(f.nom_conces, "Sans nom"))))

// Concession type
var concType = DefaultValue(f.statut_jur,
               DefaultValue(f.code_type, "Concession forestière"))

// Best area
var aSig  = Number(DefaultValue(f.sup_sig_ha, 0))
var aAdm  = Number(DefaultValue(f.sup_adm_ha, 0))
var aCCF  = Number(DefaultValue(f.sup_ccf_ha, 0))
var aFin  = Number(DefaultValue(f.sup_fin, 0))
var maxA  = 0
for (var av in [aSig, aAdm, aCCF, aFin]) { if (av > maxA) { maxA = av } }

// Attribution year
var attrYear = ""
if (!IsEmpty(f.date_d_att))  { attrYear = Text(Date(f.date_d_att),  "YYYY") }
else if (!isBlank(f.date_attr)) { attrYear = Left(txt(f.date_attr), 4) }
else if (!IsEmpty(f.date_class)) { attrYear = Text(Date(f.date_class), "YYYY") }

// ── status chips ─────────────────────────────────────────────
var chips = ""

// Situation chip
var sitArr = IIf(HasKey(SIT_COLORS, situation), SIT_COLORS[situation], null)
if (!IsEmpty(sitArr)) { chips += chip(sitArr[0], sitArr[1], sitArr[2]) }

// CCF status chip
var ccfRaw = DefaultValue(f.statu_ccf, "")
var ccfArr = IIf(HasKey(STATU_CCF, ccfRaw), STATU_CCF[ccfRaw], null)
if (!IsEmpty(ccfArr)) { chips += chip(ccfArr[0], ccfArr[1], ccfArr[2]) }
else if (!isBlank(ccfRaw)) { chips += chip(txt(ccfRaw), "#e3f2fd", "#1565c0") }

// Aménagement chip
var amgtRaw = DefaultValue(f.statu_amgt, "")
var amgtArr = IIf(HasKey(STATU_AMGT, amgtRaw), STATU_AMGT[amgtRaw], null)
if (!IsEmpty(amgtArr)) { chips += chip(amgtArr[0], amgtArr[1], amgtArr[2]) }
else if (!isBlank(amgtRaw)) { chips += chip(txt(amgtRaw), "#f3e5f5", "#6a1b9a") }

// Certification chip
if (!isBlank(f.certificat) || !isBlank(f.certific_1)) {
  chips += chip("🏅 " + txt(DefaultValue(f.certificat, f.certific_1)), "#e0f7fa", "#00838f")
}

var chipsHtml = IIf(chips == "", "",
  "<div style=\"display:flex;gap:6px;margin-bottom:10px;flex-wrap:wrap\">" + chips + "</div>")

// ── banner ───────────────────────────────────────────────────
var banner =
  "<div style=\"background:" + ACCENT + ";color:white;padding:10px 12px;border-radius:6px 6px 0 0;margin:0 0 10px 0\">"
  + "<div style=\"font-size:15px;font-weight:700\">" + txt(name) + "</div>"
  + "<div style=\"font-size:11px;opacity:0.9;margin-top:2px\">" + flag + " " + txt(country)
  + IIf(!isBlank(f.attributai), " — " + txt(f.attributai), "") + "</div>"
  + "<div style=\"font-size:10px;opacity:0.85;margin-top:4px;text-transform:uppercase;letter-spacing:0.8px\">"
  + txt(concType) + "</div></div>"

// ── breadcrumb ───────────────────────────────────────────────
var crumbs = txt(country)
if (!isBlank(province)) { crumbs += " › " + txt(province) }
var crumbHtml =
  "<div style=\"background:#efebe9;border-radius:6px;padding:7px 8px;margin-bottom:10px;font-size:12px;color:" + ACCENT + ";font-weight:500\">📍 " + crumbs + "</div>"

// ── tiles ─────────────────────────────────────────────────────
var areaTile = IIf(aSig > 0, Text(Round(aSig, 0), "#,###") + " ha",
               IIf(aAdm > 0, Text(Round(aAdm, 0), "#,###") + " ha", "—"))
var tiles =
  "<div style=\"display:flex;gap:6px;margin-bottom:10px;flex-wrap:wrap\">"
  + tile(areaTile,                                 "Superficie SIG", ACCENT)
  + tile(IIf(!isBlank(attrYear), attrYear, "—"),   "Attribution",    "#607d8b")
  + tile(IIf(!isBlank(province), txt(province),"—"),"Province",      "#2e7d32")
  + "</div>"

// ── area comparison bars ─────────────────────────────────────
var areaCard = section("📐 Comparaison des superficies", "#1565c0",
  bar("Superficie SIG (ha)",         aSig,  "#1565c0", maxA) +
  bar("Superficie administrative",   aAdm,  "#607d8b", maxA) +
  bar("Superficie CCF (ha)",         aCCF,  ACCENT,    maxA) +
  bar("Superficie finale",           aFin,  "#2e7d32", maxA))

// ── concession section ────────────────────────────────────────
var concRows =
  row("Nom concession",    txt(f.nom_de_la)) +
  row("Dénomination",      txt(f.dénominat)) +
  row("Référence",         txt(DefaultValue(f.référenc, f.ref_ccf))) +
  row("Numéro",            txt(f.numero_de)) +
  row("Code UPA",          txt(f.code_du_pa)) +
  row("Attributaire",      txt(f.attributai)) +
  row("Exploitant",        txt(f.exploitant)) +
  row("Origine capital",   txt(f.orig_capit)) +
  row("Type",              txt(f.statut_jur)) +
  row("Statut attribution",txt(f.statut_att)) +
  row("Statut classement", txt(f.statu_clas)) +
  row("Classement",        txt(f.classement)) +
  row("Statut du titre",   txt(f.statut_du)) +
  row("Province",          txt(f.province))

// ── DRC specific section ──────────────────────────────────────
var drcRows = ""
if (country == "DRC") {
  drcRows =
    row("N° Garantie approvis.", txt(f.num_ga)) +
    row("Réf. contrat CCF",      txt(f.ref_ccf)) +
    row("Statut CCF",            txt(f.statu_ccf)) +
    row("Statut aménagement",    txt(f.statu_amgt)) +
    row("Statut certification",  txt(f.statu_cert)) +
    row("Statut cert. (détail)", txt(f.statutcert)) +
    row("Superficie CCF ha",     haTxt(f.sup_ccf_ha)) +
    row("Date attribution",      dateStrTxt(f.date_attr)) +
    row("Date échéance",         dateTxt(f.date_echea)) +
    row("Date aménagement",      txt(f.date_amgt))
}

// ── dates section ─────────────────────────────────────────────
var dateRows =
  row("Date attribution",       dateTxt(f.date_d_att)) +
  row("Date classement",        dateTxt(f.date_de_cl)) +
  row("Date certification",     dateTxt(f.date_de_ce)) +
  row("Date classement (arch)", dateTxt(f.date_class)) +
  row("Date certification 1",   dateTxt(f.datcertif1)) +
  row("Date échéance",          dateTxt(f.date_echea))

// ── management section ────────────────────────────────────────
var mgmtRows =
  row("Plan d'aménagement",  txt(f.plan_d_amt)) +
  row("Certificat",          txt(f.certificat)) +
  row("Certificat (autre)",  txt(f.certific_1)) +
  row("Statut certificat",   txt(f.statutcert)) +
  row("RFA (FCFA/ha)",       IIf(!isBlank(f.rfa_ha), Text(f.rfa_ha), "")) +
  row("OFAC ID",             IIf(!isBlank(f.ofac_id) && f.ofac_id > 0, Text(f.ofac_id), "")) +
  row("ID Poster",           txt(f.idposter)) +
  row("Origine du titre",    txt(f.origine_du)) +
  row("Source données",      txt(f.origine_de)) +
  row("Commentaire",         txt(f.commentair))

// ── footer ────────────────────────────────────────────────────
var footer =
  "<div style=\"text-align:center;font-size:10px;color:#aaa;margin-top:10px;padding-top:8px;border-top:1px solid #eee\">"
