// ============================================================
// CONTRACT TIMELINE
// ============================================================

var contractTimeline = "";

if (!isBlank(contractStart) && !isBlank(contractEnd)) {
    var startMs = Number(Date(contractStart));
    var endMs = Number(Date(contractEnd));
    var nowMs = Number(Now());

    var progress = 0;

    if (!IsNan(startMs) && !IsNan(endMs) && endMs > startMs) {
        progress = Round(((nowMs - startMs) / (endMs - startMs)) * 100, 0);
    }

    if (progress < 0) {
        progress = 0;
    }

    if (progress > 100) {
        progress = 100;
    }

    var daysLeft = Round((endMs - nowMs) / 86400000, 0);
    var remaining = "Contract ended";

    if (!IsNan(daysLeft) && daysLeft > 0) {
        remaining = daysLeft + " days remaining";
    }

    var progressColor = "#4caf50";

    if (progress > 75) {
        progressColor = "#ff9800";
    }

    if (progress >= 100) {
        progressColor = "#f44336";
    }

    contractTimeline =
        "<div style=\"background:#f5f9f9; border-radius:6px; padding:8px 12px; margin-bottom:10px; border:1px solid #e0e0e0;\">"
        + "<div style=\"display:flex; justify-content:space-between; font-size:11px; color:#666; margin-bottom:4px;\">"
        + "<span>" + dateValueTxt(contractStart) + "</span>"
        + "<span style=\"font-weight:700; color:" + progressColor + ";\">" + progress + "% complete</span>"
        + "<span>" + dateValueTxt(contractEnd) + "</span>"
        + "</div>"
        + "<div style=\"background:#e0e0e0; border-radius:6px; height:10px; width:100%; overflow:hidden;\">"
        + "<div style=\"background:" + progressColor + "; height:10px; width:" + progress + "%; border-radius:6px;\"></div>"
        + "</div>"
        + "<div style=\"text-align:center; font-size:10px; color:#888; margin-top:4px;\">" + remaining + "</div>"
        + "</div>";
}


