    } else {
        var visitPct = Round((visitsDone / visitTotal) * 100, 0);

        visitSegments =
            "<div style=\"background:#e0e0e0; border-radius:6px; height:10px; width:100%; overflow:hidden;\">"
            + "<div style=\"background:#2e7d32; height:10px; width:" + visitPct + "%; border-radius:6px;\"></div>"
