// ============================================================
// LAND COVER AND FIRE RISK
// ============================================================

var lcApp = txt(val("landcoveratapplication"));
var lcAppPct = num("landcoveratapplicationpct");
var lcNow = txt(val("landcovercurrent"));
var lcNowPct = num("landcovercurrentpct");
var lcChanged = num("landcoverchanged");
var fireBurns = num("fireburncount");
var firePct = num("fireburnedpct");

// Current land cover is eligible only from the exact date obtained
// by adding three calendar months to the application date.
var showCurrentLandCover = false;
var applicationDateRaw = val("applicationdate");
if (!isBlank(applicationDateRaw)) {
    var applicationDateForComparison = Date(applicationDateRaw);
    var currentLandCoverAvailableDate = DateAdd(applicationDateForComparison, 3, "months");
    if (Now() >= currentLandCoverAvailableDate) {
        showCurrentLandCover = true;
    }
}

var hasApplicationLandCover = !isBlank(lcApp);
var hasCurrentLandCover = showCurrentLandCover && !isBlank(lcNow);
var hasVisibleLandCover = hasApplicationLandCover || hasCurrentLandCover;
var landFireCard = "";

if (hasVisibleLandCover || !isBlank(fireCat)) {
    var accent = "#607d8b";
    if (hasCurrentLandCover && lcChanged == 1) {
        accent = "#ff8f00";
    }

    var lcHtml = "";
    if (hasVisibleLandCover) {
        var applicationLandCoverHtml = "";
        var currentLandCoverHtml = "";
        var arrowHtml = "";
        var changeNoteHtml = "";

        if (hasApplicationLandCover) {
            applicationLandCoverHtml =
                "<div style=\"flex:1; background:#fff; border:1px solid #e0e0e0; border-radius:6px; padding:6px; text-align:center;\">"
                + "<div style=\"font-size:9px; color:#888; text-transform:uppercase; letter-spacing:.5px;\">At application</div>"
                + "<div style=\"font-size:12px; font-weight:700; color:#455a64; margin-top:2px;\">" + DefaultValue(lcApp, "-") + "</div>"
                + IIf(lcAppPct > 0, "<div style=\"font-size:9px; color:#999;\">" + Round(lcAppPct, 0) + "% of parcel</div>", "")
                + "</div>";
        }

        if (hasCurrentLandCover) {
            var arrowColor = "#9e9e9e";
            var currentBorderColor = "#e0e0e0";
            var currentTextColor = "#2e7d32";
            var changeNote = "unchanged";
            if (lcChanged == 1) {
                arrowColor = "#ff8f00";
                currentBorderColor = "#ffb74d";
                currentTextColor = "#e65100";
                changeNote = "changed";
            }
            if (hasApplicationLandCover) {
                arrowHtml = "<div style=\"font-size:16px; color:" + arrowColor + "; font-weight:700;\">&rarr;</div>";
            }
            currentLandCoverHtml =
                "<div style=\"flex:1; background:#fff; border:1px solid " + currentBorderColor + "; border-radius:6px; padding:6px; text-align:center;\">"
                + "<div style=\"font-size:9px; color:#888; text-transform:uppercase; letter-spacing:.5px;\">Current</div>"
                + "<div style=\"font-size:12px; font-weight:700; color:" + currentTextColor + "; margin-top:2px;\">" + DefaultValue(lcNow, "-") + "</div>"
                + IIf(lcNowPct > 0, "<div style=\"font-size:9px; color:#999;\">" + Round(lcNowPct, 0) + "% of parcel</div>", "")
                + "</div>";
            if (hasApplicationLandCover) {
                changeNoteHtml =
                    "<div style=\"font-size:10px; color:#888; margin-bottom:6px;\">Dominant land cover - "
                    + changeNote + " since application</div>";
            }
        }

        lcHtml =
            "<div style=\"display:flex; align-items:center; gap:8px; margin-bottom:6px;\">"
            + applicationLandCoverHtml + arrowHtml + currentLandCoverHtml + "</div>"
            + changeNoteHtml;
    }

    var fireHtml = "";
    if (!isBlank(fireCat)) {
        var fireBg = "#e8f5e9";
        var fireFg = "#2e7d32";
        if (fireCat == "Moderate") { fireBg = "#fff8e1"; fireFg = "#ff8f00"; }
        if (fireCat == "High") { fireBg = "#fff3e0"; fireFg = "#ef6c00"; }
        if (fireCat == "Very High") { fireBg = "#fbe9e7"; fireFg = "#c62828"; }
        var fireNote = "No burns recorded on the parcel in the last 5 years";
        if (fireBurns > 0) {
            fireNote = "Parcel burned " + Round(fireBurns, 0) + " time(s) in the last 5 years";
            if (firePct > 0) {
                fireNote = fireNote + " - " + Round(firePct, 0) + "% of the area affected";
            }
        }
        fireHtml =
            "<div style=\"display:flex; align-items:center; gap:8px;\">"
            + "<div style=\"background:" + fireBg + "; color:" + fireFg + "; padding:4px 10px; border-radius:6px; font-size:11px; font-weight:700;\">Fire risk: " + fireCat + "</div>"
            + "<div style=\"font-size:10px; color:#666;\">" + fireNote + "</div></div>";
    }

    var geeUpdateHtml = "<div style=\"font-size:9px; color:#aaa; margin-top:6px;\">Source: Google Earth Engine";
    if (!isBlank(val("geelastupdate"))) {
        geeUpdateHtml = geeUpdateHtml + " - updated " + dateTxt("geelastupdate");
    }
    geeUpdateHtml = geeUpdateHtml + "</div>";

    landFireCard =
        "<div style=\"background:#f7fafa; border-left:4px solid " + accent + "; border-radius:4px; margin-bottom:10px; padding:8px 12px 8px 8px;\">"
        + "<div style=\"font-size:10px; font-weight:700; color:" + accent + "; text-transform:uppercase; letter-spacing:.8px; margin-bottom:8px;\">Land Cover &amp; Fire Risk</div>"
        + lcHtml + fireHtml + geeUpdateHtml + "</div>";
}

// ============================================================
// TABLE SECTIONS
// ============================================================

var applicationRows =
    row("Application Code", applicationCode)
    + row("Application Status", applicationStatus)
    + row("Application Date", dateTxt("applicationdate"))
    + row("Activity Type", activityType)
    + row("Estimated Area", areaTxt(estimatedArea, 3));

var locationRows =
    row("Country", txt(val("country")))
    + row("Province", txt(val("province")))
    + row("Territory", txt(val("territory")))
    + row("Village", txt(val("village")));

var beneficiaryRows =
    row("Beneficiary Type", txt(val("beneficiarytype")))
    + row("Beneficiary Status", txt(val("beneficiarystatus")))
    + row("Gender", txt(val("beneficiarygender")))
    + row("Family Situation", txt(val("familysituation")))
    + row("Dependents", txt(val("dependents")))
    + row("Number of Community Members", txt(val("numberofcommunitymembers")));

var projectRows =
    row("Project Name", txt(val("projectname")))
    + row("Implementing Org.", txt(val("implementingorgname")))
    + row("Org. Acronym", txt(val("implementingorgacronym")))
    + row("Supporting Aggregator", aggregatorList(val("supportingaggregator")));

var contractRows = "";
if (!isBlank(contractCode) && con != null) {
    contractRows =
        row("Contract Code", contractCode)
        + row("Contract Status", conStatus)
        + row("Start", dateValueTxt(conStart))
        + row("End", dateValueTxt(conEnd))
        + row("Duration Years", conDuration)
        + row("Declared Area", areaTxt(conDeclaredArea, 3))
        + row("Contracted PES Area", areaTxt(conContractedArea, 3))
        + row("Planned Species and Density", densityList(conTreeDensity, ""));
}

var monitoringRows = "";
if (hasMonitoring == 1) {
    monitoringRows =
        row("Last Monitoring Date", dateTxt("monitoringdate"))
        + row("Monitoring Visit Code", txt(val("monitoringvisitcode")))
        + row("Contracted Area of Monitoring", areaTxt(num("contractedareaofmonitoring"), 3))
        + row(mainAreaLabel, areaTxt(plantedArea, 3))
        + row(gapAreaLabel, areaTxt(unplantedArea, 3))
        + row("Observed Trees Count", numberTxt(observedTrees, 0))
        + row("Observed Land Cover", areaTxt(observedCoverHa, 3))
        + row("Observed Land Cover %", pctTxt(observedCoverPct, 1))
        + row("Tree Species", cleanList(val("treespecies")));
}

// ============================================================
// GEOMETRY NOTE
// ============================================================

var geometryNote = "";
var geomSrc = txt(val("geometrysource"));
if (geomSrc == "monitoring_visit_shape") {
    geometryNote = "Polygon comes from the latest monitoring visit.";
}
if (geomSrc == "application_shape") {
    geometryNote = "Polygon comes from the application geometry.";
}
var geometryHtml = "";
if (geometryNote != "") {
    geometryHtml = "<div style=\"background:#fffde7; border-radius:6px; padding:6px 8px; margin-bottom:10px; font-size:10px; color:#795548;\">" + geometryNote + "</div>";
}

// ============================================================
// BUILD POPUP
// ============================================================

var popup =
    "<div style=\"font-family:Segoe UI,sans-serif; font-size:13px; color:#1a1a2e; padding:0;\">"
    + "<div style=\"background:#0d7377; color:white; padding:10px 12px; border-radius:6px 6px 0 0; margin:0 0 10px 0;\">"
    + "<div style=\"font-size:15px; font-weight:700;\">PES Application " + applicationCode + "</div>"
    + "<div style=\"font-size:11px; opacity:0.85; margin-top:2px;\">" + txt(val("projectname")) + " - " + txt(val("implementingorgacronym")) + "</div>"
    + "<div style=\"font-size:10px; opacity:0.9; margin-top:4px; text-transform:uppercase; letter-spacing:0.8px;\">" + activityLabel + "</div>"
    + "</div>"
    + "<div style=\"display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;\">" + chipsHtml + "</div>"
    + stageTracker
    + crumbHtml
    + contractTimeline
    + visitTracker
    + landFireCard
    + visuals
    + areaComparison
    + section("Application", "#0d7377", table(applicationRows))
    + section("Location", "#14a085", table(locationRows))
    + section("Beneficiary Details", "#2196f3", table(beneficiaryRows))
    + section("Project Information", "#607d8b", table(projectRows))
    + section("Contract", "#9c27b0", table(contractRows))
    + section(monitoringTitle, "#ff9800", table(monitoringRows))
    + geometryHtml
    + "<div style=\"text-align:center; font-size:10px; color:#aaa; margin-top:10px; padding-top:8px; border-top:1px solid #eee;\">"
    + "Application: " + applicationCode
    + "&nbsp;|&nbsp; Contract: " + contractCode
    + "&nbsp;|&nbsp; Synced: " + dateTxt("lastapisync")
    + "</div>"
    + "</div>";

return {
    type: "text",
    text: popup
};

