var esriLogo = "https://esri.maps.arcgis.com/sharing/rest/content/items/a8f29b955fb548909836933fa8e83d61/data"
var earthstarLogo = "https://esri.maps.arcgis.com/sharing/rest/content/items/68836f93bbf44f24866a01d90c358ee2/data"
var nearmapLogo = "https://arcgis.com/sharing/rest/content/items/079c552b2fc04345b257cd50ed4f4c06/data"

if (Provider == "Maxar" || Provider == "DigitalGlobe" || Provider == "GeoEye") {
    return maxarLogo
} else if (Provider == "Earthstar Geographics") {
    return earthstarLogo
} else if (Provider == "Nearmap" || Provider == "nearmap") {
    return nearmapLogo
} else if (Provider == "Microsoft") {
    return msLogo
} else if (Provider == "CNES/Airbus DS") {
    return airbusLogo
} else {
    return esriLogo
}
